topics.codeExample:
#include <iostream>
#include <stdexcept>

template <typename T, int Capacity = 10>
class FixedStack {
private:
    T elements[Capacity];
    int topIndex;
public:
    FixedStack() : topIndex(-1) {}

    bool push(const T& item) {
        if (topIndex >= Capacity - 1) return false;
        elements[++topIndex] = item;
        return true;
    }

    T pop() {
        if (isEmpty()) throw std::underflow_error("Stack is empty");
        return elements[topIndex--];
    }

    T top() const {
        if (isEmpty()) throw std::underflow_error("Stack is empty");
        return elements[topIndex];
    }

    bool isEmpty() const { return topIndex == -1; }
    int size() const { return topIndex + 1; }
};

int main() {
    FixedStack<int, 5> numStack;
    numStack.push(10);
    numStack.push(20);
    numStack.push(30);
    std::cout << "Stack size: " << numStack.size() << " | Top: " << numStack.top() << "\n";
    std::cout << "Popped: " << numStack.pop() << "\n";
    std::cout << "New Top: " << numStack.top() << "\n";
    return 0;
}

