#include <iostream>
#include <deque>
#include <numeric>

class MovingAverage {
    std::deque<double> m_samples;
    std::size_t m_maxWindow;
    double m_currentSum = 0.0;
public:
    MovingAverage(std::size_t window) : m_maxWindow(window) {}

    void addSample(double val) {
        m_samples.push_back(val);
        m_currentSum += val;
        if (m_samples.size() > m_maxWindow) {
            m_currentSum -= m_samples.front();
            m_samples.pop_front(); // Efficient O(1) discard
        }
    }

    double getAverage() const {
        return m_samples.empty() ? 0.0 : m_currentSum / m_samples.size();
    }
};

int main() {
    MovingAverage avg(3);
    avg.addSample(10.0);
    avg.addSample(20.0);
    avg.addSample(30.0);
    std::cout << "Avg (10, 20, 30): " << avg.getAverage() << "\n";
    avg.addSample(40.0); // 10 popped out
    std::cout << "Avg (20, 30, 40): " << avg.getAverage() << "\n";
    return 0;
}

