#include <iostream>
#include <stack>
#include <string>

bool isBalanced(const std::string& expr) {
    std::stack<char> s;
    for (char ch : expr) {
        if (ch == '(' || ch == '{' || ch == '[') {
            s.push(ch);
        } else if (ch == ')' || ch == '}' || ch == ']') {
            if (s.empty()) return false;
            char top = s.top();
            s.pop();
            if ((ch == ')' && top != '(') ||
                (ch == '}' && top != '{') ||
                (ch == ']' && top != '[')) return false;
        }
    }
    return s.empty();
}

int main() {
    std::cout << "{[()]}: " << (isBalanced("{[()]}") ? "VALID" : "INVALID") << "\n";
    std::cout << "{[(])}: " << (isBalanced("{[(])}") ? "VALID" : "INVALID") << "\n";
    return 0;
}

