    std::unordered_map<int, std::size_t> m_idIndex;
    std::map<std::string, std::size_t> m_nameIndex;
public:
    void addStudent(int id, const std::string& name, double gpa) {
        std::size_t index = m_students.size();
        m_students.push_back({id, name, gpa});
        m_idIndex[id] = index;
        m_nameIndex[name] = index;
    }

