        }
    }

    void listAlphabetical() const {
        std::cout << "Alphabetical Directory:\n";
        for (const auto& [name, idx] : m_nameIndex) {
            std::cout << " - " << name << " [ID: " << m_students[idx].id << "]\n";
        }
    }
};

int main() {
