// Tag dispatch pattern to select optimal algorithm at compile time
template <typename Iter>
void reportCategory(Iter it, std::random_access_iterator_tag) {
    std::cout << "Random-Access Iterator detected (Supports O(1) arithmetic)\n";
}

template <typename Iter>
void reportCategory(Iter it, std::bidirectional_iterator_tag) {
    std::cout << "Bidirectional Iterator detected (Requires step-by-step traversal)\n";
}

template <typename Iter>
void inspectIterator(Iter it) {
    typename std::iterator_traits<Iter>::iterator_category tag;
    reportCategory(it, tag);
}

