#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

struct StudentRecord {
    int id;
    int rawMark;
    int curvedMark;
};

int main() {
    std::vector<StudentRecord> students = {
        {101, 45, 0}, {102, 88, 0}, {103, 30, 0}, {104, 75, 0}, {105, 92, 0}
    };

    // 1. Filter: Purge failing marks (< 40) using erase-remove [O(N)]
    students.erase(std::remove_if(students.begin(), students.end(), [](const StudentRecord& s) {
        return s.rawMark < 40;
    }), students.end());

    // 2. Transform: Apply 5-point curve [O(N)]
    std::transform(students.begin(), students.end(), students.begin(), [](StudentRecord s) {
        s.curvedMark = std::min(100, s.rawMark + 5);
        return s;
    });

    // 3. Sort: Sort by curved mark descending [O(N log N)]
    std::sort(students.begin(), students.end(), [](const StudentRecord& a, const StudentRecord& b) {
        return a.curvedMark > b.curvedMark;
    });

    std::cout << "Processed Student Marks:\n";
    for (const auto& s : students) {
        std::cout << " - ID: " << s.id << " | Curved: " << s.curvedMark << "\n";
    }
    return 0;
}

