#include <iostream>
#include <vector>
#include <functional>

// Type-erased event dispatcher holding heterogeneous callables
class EventDispatcher {
    std::vector<std::function<void(int)>> listeners;
public:
    void registerListener(std::function<void(int)> listener) {
        listeners.push_back(listener);
    }

    void emit(int eventCode) {
        for (auto& fn : listeners) {
            fn(eventCode);
        }
    }
};

// Free function callback candidate
void logEvent(int code) {
    std::cout << "[Free Function] Event Logged: " << code << "\n";
}

int main() {
    EventDispatcher dispatcher;

    // Register free function
    dispatcher.registerListener(logEvent);

    // Register lambda
    dispatcher.registerListener([](int code) {
        std::cout << "[Lambda Handler] Alert triggered for code " << code << "\n";
    });

    dispatcher.emit(404);
    return 0;
}

