enum class Priority { Low = 1, Medium = 2, High = 3 };

struct Task {
    int id;
    std::string title;
    Priority priority;
    bool completed;
    Task(int i, std::string t, Priority p) : id(i), title(t), priority(p), completed(false) {}
};

struct TaskPriorityComparator {
    bool operator()(const std::shared_ptr<Task>& a, const std::shared_ptr<Task>& b) const {
        return static_cast<int>(a->priority) < static_cast<int>(b->priority); // Max-heap: High priority on top
    }
};

class TaskManager {
    std::vector<std::shared_ptr<Task>> m_tasks;
    std::map<int, std::shared_ptr<Task>> m_idMap;
public:
    void addTask(int id, const std::string& title, Priority priority) {
        if (m_idMap.find(id) != m_idMap.end()) {
            throw std::invalid_argument("Task with this ID already exists!");
        }
        auto task = std::make_shared<Task>(id, title, priority);
        m_tasks.push_back(task);
        m_idMap[id] = task;
    }

    void markCompleted(int id) {
        auto it = m_idMap.find(id);
        if (it == m_idMap.end()) throw std::out_of_range("Task ID not found!");
        it->second->completed = true;
    }

    void printTasksByPriority() {
        std::priority_queue<std::shared_ptr<Task>, std::vector<std::shared_ptr<Task>>, TaskPriorityComparator> pq;
        for (const auto& t : m_tasks) pq.push(t);

        std::cout << "Priority Triage Schedule:\n";
        while (!pq.empty()) {
            auto t = pq.top();
            pq.pop();
            std::cout << " - [Priority " << static_cast<int>(t->priority) 
                      << "] #" << t->id << ": " << t->title 
                      << " (Status: " << (t->completed ? "DONE" : "PENDING") << ")\n";
        }
    }

    void printFiltered(bool showCompleted) {
        std::cout << (showCompleted ? "Completed Tasks:" : "Pending Tasks:") << "\n";
        std::for_each(m_tasks.begin(), m_tasks.end(), [showCompleted](const auto& t) {
            if (t->completed == showCompleted) {
                std::cout << " * #" << t->id << ": " << t->title << "\n";
            }
        });
    }
};

int main() {
    TaskManager manager;
    manager.addTask(101, "Deploy Production Kubernetes Cluster", Priority::High);
    manager.addTask(102, "Update User Guide Documentation", Priority::Low);
    manager.addTask(103, "Optimize Database Query Indices", Priority::Medium);

    manager.markCompleted(101);
    manager.printTasksByPriority();
    std::cout << "\n";
    manager.printFiltered(false); // Show pending
    return 0;
}

