struct WaypointMission {
    int id;
    int emergencyLevel; // Higher runs first
    bool operator<(const WaypointMission& other) const {
        return emergencyLevel < other.emergencyLevel;
    }
};

int main() {
    std::priority_queue<WaypointMission> flightSchedule;
    flightSchedule.push({101, 1}); // Standard route
    flightSchedule.push({102, 9}); // Emergency Return to Home
    std::cout << "Next Flight Waypoint: #" << flightSchedule.top().id << "\n";
    return 0;
}

