#include <iostream>
#include <memory>
#include <vector>
#include <algorithm>

struct Task { int id; std::string name; };

int main() {
    std::vector<std::shared_ptr<Task>> tasks = {
        std::make_shared<Task>(Task{101, "Alpha"}),
        std::make_shared<Task>(Task{102, "Beta"})
    };
    auto it = std::find_if(tasks.begin(), tasks.end(), [](const auto& t) { return t->id == 102; });
    if (it != tasks.end()) {
        std::cout << "Found: " << (*it)->name << "\n";
    }
    return 0;
}

